// Get the profile data from either direct payload or nested profileData
const profile = $json.body.profileData || $json.body;

// Safely access nested properties with fallbacks
const studentData = {
  personalInfo: {
    name: profile?.name || '',
    email: profile?.email || '',
    phone: profile?.phone || '',
    address: profile?.address || '',
    linkedin: profile?.linkedin || ''
  },
  academics: {
    age: profile?.age || 18,
    educationLevel: profile?.education_level || profile?.educationLevel || '',
    gradingSystem: profile?.grading_system || profile?.gradingSystem || '',
    academicScore: profile?.academic_score || profile?.academicScore || 0,
    standardizedTest: profile?.standardized_test || profile?.standardizedTest || 'none',
    testScore: profile?.test_score || profile?.testScore || 0
  },
  preferences: {
    targetCountries: profile?.target_countries || profile?.targetCountries || [],
    studyLevel: profile?.study_level || profile?.studyLevel || '',
    budgetMin: profile?.budget_min || profile?.budgetMin || 20000,
    budgetMax: profile?.budget_max || profile?.budgetMax || 80000,
    scholarshipInterest: profile?.scholarship_interest || profile?.scholarshipInterest || false,
    subjects: profile?.subjects || [],
    extracurriculars: profile?.extracurriculars || [],
    careerGoals: profile?.career_goals || profile?.careerGoals || ''
  },
  experience: {
    organization: profile?.organization || '',
    designation: profile?.designation || '',
    bio: profile?.bio || '',
    skills: profile?.skills || []
  }
};

return { studentData };

const data = $json.studentData;

const prompt = `You are an expert student counselor with 20 years of experience. Based on this student profile, write a personalized, encouraging message (3-4 paragraphs). Address their academics, goals, and university search strategy with warmth and professionalism.

STUDENT: ${data.personalInfo.name}
AGE: ${data.academics.age}
ACADEMIC SCORE: ${data.academics.academicScore} (${data.academics.gradingSystem})
TEST: ${data.academics.standardizedTest} (${data.academics.testScore})
GOALS: ${data.preferences.careerGoals || 'Not specified'}
SUBJECTS: ${data.preferences.subjects.join(', ')}
TARGET COUNTRIES: ${data.preferences.targetCountries.join(', ')}
BUDGET: $${data.preferences.budgetMin}-$${data.preferences.budgetMax}

Write an encouraging, personalized counselor message.`;

return { prompt };

const response = $json.body;

if (!response.candidates || response.candidates.length === 0) {
  throw new Error('No response from Gemini API');
}

const counselorMessage = response.candidates[0].content.parts[0].text;

return { counselorMessage };

const data = $json.studentData;

// Sample university database with attributes
const universities = [
  { name: "University of California, Berkeley", country: "USA", city: "Berkeley", ranking: 5, tuition: 45000, acceptance_rate: 15, specialties: ["STEM", "Engineering", "Computer Science"] },
  { name: "Stanford University", country: "USA", city: "Stanford", ranking: 3, tuition: 60000, acceptance_rate: 3, specialties: ["STEM", "Technology", "Business"] },
  { name: "MIT", country: "USA", city: "Cambridge", ranking: 1, tuition: 62000, acceptance_rate: 4, specialties: ["STEM", "Engineering", "Computer Science"] },
  { name: "Harvard University", country: "USA", city: "Cambridge", ranking: 2, tuition: 60000, acceptance_rate: 3, specialties: ["Liberal Arts", "Business", "Law"] },
  { name: "Yale University", country: "USA", city: "New Haven", ranking: 4, tuition: 62000, acceptance_rate: 4, specialties: ["Liberal Arts", "Drama", "Music"] },
  { name: "University of Toronto", country: "Canada", city: "Toronto", ranking: 20, tuition: 15000, acceptance_rate: 20, specialties: ["STEM", "Medicine", "Business"] },
  { name: "University of British Columbia", country: "Canada", city: "Vancouver", ranking: 25, tuition: 16000, acceptance_rate: 23, specialties: ["STEM", "Commerce", "Engineering"] },
  { name: "McGill University", country: "Canada", city: "Montreal", ranking: 26, tuition: 14000, acceptance_rate: 24, specialties: ["Medicine", "Engineering", "Science"] },
  { name: "University of Waterloo", country: "Canada", city: "Waterloo", ranking: 30, tuition: 17000, acceptance_rate: 30, specialties: ["Engineering", "Computer Science", "Mathematics"] },
  { name: "University of Alberta", country: "Canada", city: "Edmonton", ranking: 35, tuition: 12000, acceptance_rate: 32, specialties: ["Engineering", "Science", "Medicine"] },
  { name: "Oxford University", country: "UK", city: "Oxford", ranking: 2, tuition: 35000, acceptance_rate: 2, specialties: ["Liberal Arts", "Law", "History"] },
  { name: "Cambridge University", country: "UK", city: "Cambridge", ranking: 3, tuition: 35000, acceptance_rate: 2, specialties: ["STEM", "Mathematics", "Physics"] },
  { name: "Imperial College London", country: "UK", city: "London", ranking: 8, tuition: 38000, acceptance_rate: 8, specialties: ["STEM", "Engineering", "Medicine"] },
  { name: "ETH Zurich", country: "Switzerland", city: "Zurich", ranking: 10, tuition: 1200, acceptance_rate: 5, specialties: ["STEM", "Engineering", "Mathematics"] },
  { name: "National University of Singapore", country: "Singapore", city: "Singapore", ranking: 11, tuition: 23000, acceptance_rate: 25, specialties: ["STEM", "Engineering", "Business"] }
];

// Scoring function
const scoreUniversity = (uni) => {
  let score = 0;

  // Budget match (higher is better if within budget)
  if (uni.tuition <= data.preferences.budgetMax && uni.tuition >= data.preferences.budgetMin) {
    score += 30;
  } else if (uni.tuition <= data.preferences.budgetMax) {
    score += 20;
  }

  // Country preference
  if (data.preferences.targetCountries.includes(uni.country)) {
    score += 25;
  }

  // Subject match
  const matchingSubjects = uni.specialties.filter(s => data.preferences.subjects.some(sub => sub.toLowerCase().includes(s.toLowerCase()) || s.toLowerCase().includes(sub.toLowerCase())));
  score += matchingSubjects.length * 15;

  // Academic level match
  if (data.academics.academicScore >= 85 && uni.ranking <= 50) score += 20;
  if (data.academics.academicScore >= 75 && uni.ranking <= 100) score += 15;
  if (data.academics.academicScore >= 65) score += 10;

  return score;
};

// Score and categorize universities
const scoredUnis = universities.map(uni => ({
  ...uni,
  score: scoreUniversity(uni)
})).sort((a, b) => b.score - a.score);

// Split into safe, target, dream
const matchedUniversities = {
  safe: scoredUnis.slice(0, 5).map(u => ({ name: u.name, country: u.country, city: u.city, score: u.score, acceptance_rate: u.acceptance_rate })),
  target: scoredUnis.slice(5, 10).map(u => ({ name: u.name, country: u.country, city: u.city, score: u.score, acceptance_rate: u.acceptance_rate })),
  dream: scoredUnis.slice(10, 15).map(u => ({ name: u.name, country: u.country, city: u.city, score: u.score, acceptance_rate: u.acceptance_rate }))
};

return { matchedUniversities };

return {
  timestamp: new Date().toISOString(),
  studentEmail: $json.studentData.personalInfo.email,
  status: 'success',
  counselorMessageLength: $json.counselorMessage.length,
  matchCount: $json.matchedUniversities.safe.length + $json.matchedUniversities.target.length + $json.matchedUniversities.dream.length,
  message: 'Counselor email sent successfully'
};
